/**
 * Canonical store destinations for 4 Our Life (consumer app).
 *
 * Both listings are live. This module is the single source of truth for every
 * download CTA on the site — hero, final CTA, footer and the download banner —
 * so a store ID change is one edit here rather than eight scattered hrefs that
 * drift apart. Previously all eight were `href="#"`, which is why the site had
 * no working path to either store.
 *
 * The matching QR codes are NOT hand-authored. They are generated by
 * `scripts/generate-store-qr.js` at the workspace root, which writes the SVG
 * masters into `public/qr/` and aborts if these IDs ever drift from the mobile
 * repo's documented source of truth
 * (`4OurLife-MobileApp/apps/consumer/store/README.md`).
 */

export const APPLE_APP_ID = "6754759396";
export const ANDROID_PACKAGE = "com.fourourlifeapppay.fourourlifeapppay";

export const APP_STORE_URL = `https://apps.apple.com/app/id${APPLE_APP_ID}`;
export const PLAY_STORE_URL = `https://play.google.com/store/apps/details?id=${ANDROID_PACKAGE}`;

/**
 * Vector QR masters under `public/qr/`. Being SVG they scale to any size
 * without going soft, so the same file serves a 96px CTA and a banner.
 */
export const APP_STORE_QR = "/qr/app-store.svg";
export const PLAY_STORE_QR = "/qr/google-play.svg";
